p=await open(1180,'?case=desktop');check('desktop exact/room fit',await p.locator('.scroll-button').count()===0,'8 × 140 fits 1148 inner px');await p.close();
p=await open(390,'?case=both');const gap=await p.evaluate(()=>{let a=document.querySelector('.doc-tab-wrap').getBoundingClientRect(),b=document.querySelector('.doc-count').getBoundingClientRect();return b.left-a.right});check('narrow six pixel gap',gap===6,`gap ${gap}`);await p.getByLabel(/項目を切り替える/).click();check('item chooser focus',await p.evaluate(()=>document.activeElement.matches('.item-menu button')),'first hidden item focused');await p.keyboard.press('Escape');check('item escape focus return',(await p.evaluate(()=>document.activeElement.className)).includes('item-count'),'trigger focused');await p.getByLabel(/文書を切り替える/).click();await p.keyboard.press('Escape');check('document escape focus return',(await p.evaluate(()=>document.activeElement.className)).includes('doc-count'),'trigger focused');await p.close();
p=await open(760,'?case=parent');const selectedBefore=await p.locator('.doc-tab[aria-selected=true]').getAttribute('aria-label');await p.locator('.doc-tab-wrap').nth(2).hover();await p.locator('.doc-tab-wrap').nth(2).getByRole('button',{name:/を閉じる/}).click();check('inactive close preserves selection',(await p.locator('.doc-tab[aria-selected=true]').getAttribute('aria-label'))===selectedBefore,'selection unchanged');await p.locator('.doc-tab[aria-selected=true]').locator('..').getByRole('button',{name:/を閉じる/}).click();check('selected close chooses following',(await p.locator('.doc-tab[aria-selected=true]').getAttribute('aria-label'))==='受注管理、東日本','following selected');check('close focus',await p.evaluate(()=>document.activeElement.getAttribute('role'))==='tab','remaining tab focused');await p.close();
p=await open(760,'?case=fit');await p.locator('.item-tab').nth(1).click();await p.locator('.doc-tab').nth(1).click();await p.locator('.doc-tab').nth(0).click();check('item selection preserved',(await p.locator('.item-tab[aria-selected=true]').textContent())==='履歴','履歴 restored');await p.close();
p=await open(390,'?case=unknown');check('unknown case fallback',await p.getByLabel(/文書を切り替える/).textContent().then(x=>x.includes('ほか4')),'both case used');await p.screenshot({path:'/bench/app/evidence/final-narrow.png',fullPage:true});await p.close();
fs.writeFileSync('/bench/app/evidence/final-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await b.close()})().catch(e=>{console.error(e);process.exit(1)});
